/* xxh32.c - 32-bit xxHash implementation. */
#include "xxh32.h"
#include <string.h>

#define P1 2654435761U
#define P2 2246822519U
#define P3 3266489917U
#define P4 668265263U
#define P5 374761393U

static uint32_t rl32(uint32_t x, int r) { return (x << r) | (x >> (32 - r)); }

static uint32_t rd32(const void* p)
{
    uint32_t v;
    memcpy(&v, p, sizeof(v));
    return v; /* little-endian hosts only */
}

static uint32_t round32(uint32_t acc, uint32_t in)
{
    acc += in * P2;
    acc = rl32(acc, 13);
    acc *= P1;
    return acc;
}

static uint32_t avalanche(uint32_t h)
{
    h ^= h >> 15;
    h *= P2;
    h ^= h >> 13;
    h *= P3;
    h ^= h >> 16;
    return h;
}

static uint32_t finalize(uint32_t h, const uint8_t* p, size_t len)
{
    len &= 15;
    while (len >= 4) {
        h += rd32(p) * P3;
        p += 4;
        h = rl32(h, 17) * P4;
        len -= 4;
    }
    while (len > 0) {
        h += (*p++) * P5;
        h = rl32(h, 11) * P1;
        len--;
    }
    return avalanche(h);
}

void XH32_reset(XH32_state* st, uint32_t seed)
{
    memset(st, 0, sizeof(*st));
    st->v[0] = seed + P1 + P2;
    st->v[1] = seed + P2;
    st->v[2] = seed;
    st->v[3] = seed - P1;
}

void XH32_update(XH32_state* st, const void* input, size_t len)
{
    const uint8_t* p = (const uint8_t*)input;
    const uint8_t* const end = p + len;

    if (input == NULL) return;
    st->total_len_32 += (uint32_t)len;
    st->large_len |= (len >= 16) | (st->total_len_32 >= 16);

    if (st->memsize + len < 16) {
        memcpy((uint8_t*)st->mem32 + st->memsize, input, len);
        st->memsize += (uint32_t)len;
        return;
    }

    if (st->memsize) {
        memcpy((uint8_t*)st->mem32 + st->memsize, input, 16 - st->memsize);
        {
            const uint8_t* m = (const uint8_t*)st->mem32;
            int i;
            for (i = 0; i < 4; i++) st->v[i] = round32(st->v[i], rd32(m + 4 * i));
        }
        p += 16 - st->memsize;
        st->memsize = 0;
    }

    if (p <= end - 16) {
        const uint8_t* const limit = end - 16;
        uint32_t v0 = st->v[0], v1 = st->v[1], v2 = st->v[2], v3 = st->v[3];
        do {
            v0 = round32(v0, rd32(p)); p += 4;
            v1 = round32(v1, rd32(p)); p += 4;
            v2 = round32(v2, rd32(p)); p += 4;
            v3 = round32(v3, rd32(p)); p += 4;
        } while (p <= limit);
        st->v[0] = v0; st->v[1] = v1; st->v[2] = v2; st->v[3] = v3;
    }

    if (p < end) {
        memcpy(st->mem32, p, (size_t)(end - p));
        st->memsize = (uint32_t)(end - p);
    }
}

uint32_t XH32_digest(const XH32_state* st)
{
    uint32_t h;
    if (st->large_len)
        h = rl32(st->v[0], 1) + rl32(st->v[1], 7) + rl32(st->v[2], 12) + rl32(st->v[3], 18);
    else
        h = st->v[2] + P5;
    h += st->total_len_32;
    return finalize(h, (const uint8_t*)st->mem32, st->memsize);
}

uint32_t XH32(const void* input, size_t len, uint32_t seed)
{
    const uint8_t* p = (const uint8_t*)input;
    uint32_t h;

    if (len >= 16) {
        const uint8_t* const limit = p + len - 16;
        uint32_t v0 = seed + P1 + P2;
        uint32_t v1 = seed + P2;
        uint32_t v2 = seed;
        uint32_t v3 = seed - P1;
        do {
            v0 = round32(v0, rd32(p)); p += 4;
            v1 = round32(v1, rd32(p)); p += 4;
            v2 = round32(v2, rd32(p)); p += 4;
            v3 = round32(v3, rd32(p)); p += 4;
        } while (p <= limit);
        h = rl32(v0, 1) + rl32(v1, 7) + rl32(v2, 12) + rl32(v3, 18);
    } else {
        h = seed + P5;
    }
    h += (uint32_t)len;
    return finalize(h, p, len);
}

