/* lz4blk.h - LZ4 block format compression / decompression. */
#ifndef LZ4BLK_H
#define LZ4BLK_H

#include <stddef.h>
#include <stdint.h>

#define LZ4_MEMORY_USAGE   14
#define LZ4_HASHLOG        (LZ4_MEMORY_USAGE - 2)
#define LZ4_HASH_SIZE_U32  (1u << LZ4_HASHLOG)
#define LZ4_MAX_INPUT_SIZE 0x7E000000
#define LZ4_DISTANCE_MAX   65535
#define LZ4_ACCELERATION_MAX 65537

int LZ4_compressBound(int isize);

/* Streaming-capable state used for both one-shot and linked-block modes. */
typedef struct {
    uint32_t hashTable[LZ4_HASH_SIZE_U32];
    uint32_t currentOffset;
    uint32_t tableType;
    const uint8_t* dictionary;
    uint32_t dictSize;
} LZ4_cstream;

void LZ4_initStream(LZ4_cstream* s);
void LZ4_resetStream_fast(LZ4_cstream* s);
int  LZ4_loadDict(LZ4_cstream* s, const char* dict, int dictSize);
int  LZ4_compress_fast_continue(LZ4_cstream* s, const char* src, char* dst,
                                int srcSize, int dstCapacity, int acceleration);
int  LZ4_saveDict(LZ4_cstream* s, char* safeBuffer, int dictSize);

/* One-shot compression with an externally supplied (reusable) state. */
int LZ4_compress_fast_extState_fastReset(LZ4_cstream* s, const char* src, char* dst,
                                         int srcSize, int dstCapacity, int acceleration);

/* Decompression */
int LZ4_decompress_safe(const char* src, char* dst, int cSize, int dstCapacity);
int LZ4_decompress_safe_usingDict(const char* src, char* dst, int cSize, int dstCapacity,
                                  const char* dictStart, int dictSize);

#endif

