/* lz4blk.c - LZ4 block format codec. */
#include "lz4blk.h"
#include <string.h>

#define MINMATCH 4
#define WILDCOPYLENGTH 8
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_minLength (MFLIMIT + 1)
#define MATCH_SAFEGUARD_DISTANCE ((2 * WILDCOPYLENGTH) - MINMATCH)
#define ML_BITS 4
#define ML_MASK ((1u << ML_BITS) - 1)
#define RUN_BITS (8 - ML_BITS)
#define RUN_MASK ((1u << RUN_BITS) - 1)
#define KB 1024
#define LZ4_64Klimit ((64 * KB) + (MFLIMIT - 1))
#define LZ4_skipTrigger 6
#define HASH_UNIT 8

typedef uint8_t BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;

enum { clearedTable = 0, byU32 = 2, byU16 = 3 };
enum { noDict = 0, withPrefix64k, usingExtDict };
enum { noDictIssue = 0, dictSmall };
enum { notLimited = 0, limitedOutput };

static U16 rd16(const void* p) { U16 v; memcpy(&v, p, 2); return v; }
static U32 rd32(const void* p) { U32 v; memcpy(&v, p, 4); return v; }
static U64 rd64(const void* p) { U64 v; memcpy(&v, p, 8); return v; }
static void wr16(void* p, U16 v) { memcpy(p, &v, 2); }
static void wr32(void* p, U32 v) { memcpy(p, &v, 4); }

int LZ4_compressBound(int isize)
{
    return (unsigned)isize > (unsigned)LZ4_MAX_INPUT_SIZE ? 0 : isize + (isize / 255) + 16;
}

static U32 hash4(U32 seq, int tableType)
{
    if (tableType == byU16) return (seq * 2654435761U) >> ((MINMATCH * 8) - (LZ4_HASHLOG + 1));
    return (seq * 2654435761U) >> ((MINMATCH * 8) - LZ4_HASHLOG);
}

static U32 hash5(U64 seq)
{
    const U64 prime5bytes = 889523592379ULL;
    return (U32)(((seq << 24) * prime5bytes) >> (64 - LZ4_HASHLOG));
}

static U32 hashPosition(const void* p, int tableType)
{
    if (tableType != byU16) return hash5(rd64(p));
    return hash4(rd32(p), tableType);
}

static void putIndexOnHash(U32 idx, U32 h, void* tableBase, int tableType)
{
    if (tableType == byU32) { ((U32*)tableBase)[h] = idx; }
    else { ((U16*)tableBase)[h] = (U16)idx; }
}

static U32 getIndexOnHash(U32 h, const void* tableBase, int tableType)
{
    if (tableType == byU32) return ((const U32*)tableBase)[h];
    return ((const U16*)tableBase)[h];
}

static void putPosition(const BYTE* p, void* tableBase, int tableType, const BYTE* srcBase)
{
    U32 const h = hashPosition(p, tableType);
    putIndexOnHash((U32)(p - srcBase), h, tableBase, tableType);
}

static unsigned countMatch(const BYTE* pIn, const BYTE* pMatch, const BYTE* pInLimit)
{
    const BYTE* const pStart = pIn;

    if (pIn < pInLimit - (sizeof(U64) - 1)) {
        U64 const diff = rd64(pMatch) ^ rd64(pIn);
        if (!diff) { pIn += sizeof(U64); pMatch += sizeof(U64); }
        else return (unsigned)(__builtin_ctzll(diff) >> 3);
    }

    while (pIn < pInLimit - (sizeof(U64) - 1)) {
        U64 const diff = rd64(pMatch) ^ rd64(pIn);
        if (!diff) { pIn += sizeof(U64); pMatch += sizeof(U64); continue; }
        pIn += (unsigned)(__builtin_ctzll(diff) >> 3);
        return (unsigned)(pIn - pStart);
    }

    if ((pIn < (pInLimit - 3)) && (rd32(pMatch) == rd32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < (pInLimit - 1)) && (rd16(pMatch) == rd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

static void wildCopy8(void* dstPtr, const void* srcPtr, void* dstEnd)
{
    BYTE* d = (BYTE*)dstPtr;
    const BYTE* s = (const BYTE*)srcPtr;
    BYTE* const e = (BYTE*)dstEnd;
    do { memcpy(d, s, 8); d += 8; s += 8; } while (d < e);
}

/* ---------------------------------------------------------------- *
 *  Compression core
 * ---------------------------------------------------------------- */

static int compress_generic(LZ4_cstream* const cctx,
                            const char* const src, char* const dst,
                            const int srcSize, const int dstCapacity,
                            const int outputDirective, const int tableType,
                            const int dictDirective, const int dictIssue,
                            const int acceleration)
{
    int result;
    const BYTE* ip = (const BYTE*)src;

    U32 const startIndex = cctx->currentOffset;
    const BYTE* base = (const BYTE*)src - startIndex;
    const BYTE* lowLimit;

    const BYTE* const dictionary = cctx->dictionary;
    const U32 dictSize = cctx->dictSize;

    int const maybe_extMem = (dictDirective == usingExtDict);
    U32 const prefixIdxLimit = startIndex - dictSize;
    const BYTE* const dictEnd = dictionary ? dictionary + dictSize : dictionary;
    const BYTE* anchor = (const BYTE*)src;
    const BYTE* const iend = ip + srcSize;
    const BYTE* const mflimitPlusOne = iend - MFLIMIT + 1;
    const BYTE* const matchlimit = iend - LASTLITERALS;

    const BYTE* dictBase = (dictionary == NULL) ? NULL : dictionary + dictSize - startIndex;

    BYTE* op = (BYTE*)dst;
    BYTE* const olimit = op + dstCapacity;

    U32 offset = 0;
    U32 forwardH;

    if ((tableType == byU16) && (srcSize >= LZ4_64Klimit)) return 0;

    lowLimit = (const BYTE*)src - (dictDirective == withPrefix64k ? dictSize : 0);

    cctx->dictSize += (U32)srcSize;
    cctx->currentOffset += (U32)srcSize;
    cctx->tableType = (U32)tableType;

    if (srcSize < LZ4_minLength) goto _last_literals;

    /* First Byte */
    {   U32 const h = hashPosition(ip, tableType);
        putIndexOnHash(startIndex, h, cctx->hashTable, tableType);
    }
    ip++;
    forwardH = hashPosition(ip, tableType);

    for (;;) {
        const BYTE* match;
        BYTE* token;

        /* Find a match */
        {   const BYTE* forwardIp = ip;
            int step = 1;
            int searchMatchNb = acceleration << LZ4_skipTrigger;
            do {
                U32 const h = forwardH;
                U32 const current = (U32)(forwardIp - base);
                U32 matchIndex = getIndexOnHash(h, cctx->hashTable, tableType);

                ip = forwardIp;
                forwardIp += step;
                step = (searchMatchNb++ >> LZ4_skipTrigger);

                if (forwardIp > mflimitPlusOne) goto _last_literals;

                if (dictDirective == usingExtDict) {
                    if (matchIndex < startIndex) {
                        match = dictBase + matchIndex;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = (const BYTE*)src;
                    }
                } else {
                    match = base + matchIndex;
                }
                putIndexOnHash(current, h, cctx->hashTable, tableType);
                forwardH = hashPosition(forwardIp, tableType);

                if ((dictIssue == dictSmall) && (matchIndex < prefixIdxLimit)) continue;
                if ((tableType != byU16) && (matchIndex + LZ4_DISTANCE_MAX < current)) continue;

                if (rd32(match) == rd32(ip)) {
                    if (maybe_extMem) offset = current - matchIndex;
                    break;
                }
            } while (1);
        }

        /* Catch up */
        while (((ip > anchor) & (match > lowLimit)) && (ip[-1] == match[-1])) { ip--; match--; }

        /* Encode Literals */
        {   unsigned const litLength = (unsigned)(ip - anchor);
            token = op++;
            if ((outputDirective == limitedOutput) &&
                (op + litLength + (2 + 1 + LASTLITERALS) + (litLength / 255) > olimit))
                return 0;
            if (litLength >= RUN_MASK) {
                unsigned len = litLength - RUN_MASK;
                *token = (BYTE)(RUN_MASK << ML_BITS);
                for (; len >= 255; len -= 255) *op++ = 255;
                *op++ = (BYTE)len;
            } else {
                *token = (BYTE)(litLength << ML_BITS);
            }
            wildCopy8(op, anchor, op + litLength);
            op += litLength;
        }

_next_match:
        /* Encode Offset */
        if (maybe_extMem) { wr16(op, (U16)offset); op += 2; }
        else { wr16(op, (U16)(ip - match)); op += 2; }

        /* Encode MatchLength */
        {   unsigned matchCode;

            if ((dictDirective == usingExtDict) && (lowLimit == dictionary)) {
                const BYTE* limit = ip + (size_t)(dictEnd - match);
                if (limit > matchlimit) limit = matchlimit;
                matchCode = countMatch(ip + MINMATCH, match + MINMATCH, limit);
                ip += (size_t)matchCode + MINMATCH;
                if (ip == limit) {
                    unsigned const more = countMatch(limit, (const BYTE*)src, matchlimit);
                    matchCode += more;
                    ip += more;
                }
            } else {
                matchCode = countMatch(ip + MINMATCH, match + MINMATCH, matchlimit);
                ip += (size_t)matchCode + MINMATCH;
            }

            if ((outputDirective == limitedOutput) &&
                (op + (1 + LASTLITERALS) + (matchCode + 240) / 255 > olimit))
                return 0;

            if (matchCode >= ML_MASK) {
                *token += (BYTE)ML_MASK;
                matchCode -= ML_MASK;
                wr32(op, 0xFFFFFFFFu);
                while (matchCode >= 4 * 255) {
                    op += 4;
                    wr32(op, 0xFFFFFFFFu);
                    matchCode -= 4 * 255;
                }
                op += matchCode / 255;
                *op++ = (BYTE)(matchCode % 255);
            } else {
                *token += (BYTE)matchCode;
            }
        }
        anchor = ip;

        /* Test end of chunk */
        if (ip >= mflimitPlusOne) break;

        /* Fill table */
        {   U32 const h = hashPosition(ip - 2, tableType);
            U32 const idx = (U32)((ip - 2) - base);
            putIndexOnHash(idx, h, cctx->hashTable, tableType);
        }

        /* Test next position */
        {   U32 const h = hashPosition(ip, tableType);
            U32 const current = (U32)(ip - base);
            U32 matchIndex = getIndexOnHash(h, cctx->hashTable, tableType);
            if (dictDirective == usingExtDict) {
                if (matchIndex < startIndex) {
                    match = dictBase + matchIndex;
                    lowLimit = dictionary;
                } else {
                    match = base + matchIndex;
                    lowLimit = (const BYTE*)src;
                }
            } else {
                match = base + matchIndex;
            }
            putIndexOnHash(current, h, cctx->hashTable, tableType);
            if (((dictIssue == dictSmall) ? (matchIndex >= prefixIdxLimit) : 1)
                && (((tableType == byU16) && (LZ4_DISTANCE_MAX == 65535)) ? 1
                    : (matchIndex + LZ4_DISTANCE_MAX >= current))
                && (rd32(match) == rd32(ip))) {
                token = op++;
                *token = 0;
                if (maybe_extMem) offset = current - matchIndex;
                goto _next_match;
            }
        }

        /* Prepare next loop */
        forwardH = hashPosition(++ip, tableType);
    }

_last_literals:
    {   size_t lastRun = (size_t)(iend - anchor);
        if ((outputDirective == limitedOutput) &&
            (op + lastRun + 1 + ((lastRun + 255 - RUN_MASK) / 255) > olimit))
            return 0;
        if (lastRun >= RUN_MASK) {
            size_t accumulator = lastRun - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRun << ML_BITS);
        }
        memcpy(op, anchor, lastRun);
        op += lastRun;
    }

    result = (int)(((char*)op) - dst);
    return result;
}

static void prepareTable(LZ4_cstream* const cctx, const int inputSize, const int tableType)
{
    if ((int)cctx->tableType != clearedTable) {
        if ((int)cctx->tableType != tableType
            || ((tableType == byU16) && cctx->currentOffset + (unsigned)inputSize >= 0xFFFFu)
            || ((tableType == byU32) && cctx->currentOffset > (1u << 30))
            || inputSize >= 4 * KB) {
            memset(cctx->hashTable, 0, sizeof(cctx->hashTable));
            cctx->currentOffset = 0;
            cctx->tableType = clearedTable;
        }
    }

    if (cctx->currentOffset != 0 && tableType == byU32) cctx->currentOffset += 64 * KB;

    cctx->dictionary = NULL;
    cctx->dictSize = 0;
}

void LZ4_initStream(LZ4_cstream* s)
{
    memset(s, 0, sizeof(*s));
}

void LZ4_resetStream_fast(LZ4_cstream* s)
{
    prepareTable(s, 0, byU32);
}

int LZ4_compress_fast_extState_fastReset(LZ4_cstream* s, const char* src, char* dst,
                                         int srcSize, int dstCapacity, int acceleration)
{
    if (acceleration < 1) acceleration = 1;
    if (acceleration > LZ4_ACCELERATION_MAX) acceleration = LZ4_ACCELERATION_MAX;

    if (dstCapacity >= LZ4_compressBound(srcSize)) {
        if (srcSize < LZ4_64Klimit) {
            const int tableType = byU16;
            prepareTable(s, srcSize, tableType);
            if (s->currentOffset)
                return compress_generic(s, src, dst, srcSize, dstCapacity, notLimited,
                                        tableType, noDict, dictSmall, acceleration);
            return compress_generic(s, src, dst, srcSize, dstCapacity, notLimited,
                                    tableType, noDict, noDictIssue, acceleration);
        } else {
            const int tableType = byU32;
            prepareTable(s, srcSize, tableType);
            return compress_generic(s, src, dst, srcSize, dstCapacity, notLimited,
                                    tableType, noDict, noDictIssue, acceleration);
        }
    } else {
        if (srcSize < LZ4_64Klimit) {
            const int tableType = byU16;
            prepareTable(s, srcSize, tableType);
            if (s->currentOffset)
                return compress_generic(s, src, dst, srcSize, dstCapacity, limitedOutput,
                                        tableType, noDict, dictSmall, acceleration);
            return compress_generic(s, src, dst, srcSize, dstCapacity, limitedOutput,
                                    tableType, noDict, noDictIssue, acceleration);
        } else {
            const int tableType = byU32;
            prepareTable(s, srcSize, tableType);
            return compress_generic(s, src, dst, srcSize, dstCapacity, limitedOutput,
                                    tableType, noDict, noDictIssue, acceleration);
        }
    }
}

int LZ4_loadDict(LZ4_cstream* dict, const char* dictionary, int dictSize)
{
    const int tableType = byU32;
    const BYTE* p = (const BYTE*)dictionary;
    const BYTE* const dictEnd = p + dictSize;
    U32 idx32;

    LZ4_initStream(dict);
    dict->currentOffset += 64 * KB;

    if (dictSize < HASH_UNIT) return 0;

    if ((dictEnd - p) > 64 * KB) p = dictEnd - 64 * KB;
    dict->dictionary = p;
    dict->dictSize = (U32)(dictEnd - p);
    dict->tableType = (U32)tableType;
    idx32 = dict->currentOffset - dict->dictSize;

    while (p <= dictEnd - HASH_UNIT) {
        U32 const h = hashPosition(p, tableType);
        putIndexOnHash(idx32, h, dict->hashTable, tableType);
        p += 3;
        idx32 += 3;
    }

    return (int)dict->dictSize;
}

static void renormDictT(LZ4_cstream* d, int nextSize)
{
    if (d->currentOffset + (unsigned)nextSize > 0x80000000u) {
        U32 const delta = d->currentOffset - 64 * KB;
        const BYTE* dictEnd = d->dictionary + d->dictSize;
        int i;
        for (i = 0; i < (int)LZ4_HASH_SIZE_U32; i++) {
            if (d->hashTable[i] < delta) d->hashTable[i] = 0;
            else d->hashTable[i] -= delta;
        }
        d->currentOffset = 64 * KB;
        if (d->dictSize > 64 * KB) d->dictSize = 64 * KB;
        d->dictionary = dictEnd - d->dictSize;
    }
}

int LZ4_compress_fast_continue(LZ4_cstream* s, const char* source, char* dest,
                               int inputSize, int maxOutputSize, int acceleration)
{
    const int tableType = byU32;
    const char* dictEnd = s->dictSize ? (const char*)s->dictionary + s->dictSize : NULL;

    renormDictT(s, inputSize);
    if (acceleration < 1) acceleration = 1;
    if (acceleration > LZ4_ACCELERATION_MAX) acceleration = LZ4_ACCELERATION_MAX;

    /* invalidate tiny dictionaries */
    if ((s->dictSize < 4) && (dictEnd != source) && (inputSize > 0)) {
        s->dictSize = 0;
        s->dictionary = (const BYTE*)source;
        dictEnd = source;
    }

    /* check overlapping input/dictionary space */
    {   const char* const sourceEnd = source + inputSize;
        if ((sourceEnd > (const char*)s->dictionary) && (sourceEnd < dictEnd)) {
            s->dictSize = (U32)(dictEnd - sourceEnd);
            if (s->dictSize > 64 * KB) s->dictSize = 64 * KB;
            if (s->dictSize < 4) s->dictSize = 0;
            s->dictionary = (const BYTE*)dictEnd - s->dictSize;
        }
    }

    /* prefix mode : source data follows dictionary */
    if (dictEnd == source) {
        if ((s->dictSize < 64 * KB) && (s->dictSize < s->currentOffset))
            return compress_generic(s, source, dest, inputSize, maxOutputSize, limitedOutput,
                                    tableType, withPrefix64k, dictSmall, acceleration);
        return compress_generic(s, source, dest, inputSize, maxOutputSize, limitedOutput,
                                tableType, withPrefix64k, noDictIssue, acceleration);
    }

    /* external dictionary mode */
    {   int const result = compress_generic(s, source, dest, inputSize, maxOutputSize,
                                            limitedOutput, tableType, usingExtDict,
                                            noDictIssue, acceleration);
        s->dictionary = (const BYTE*)source;
        s->dictSize = (U32)inputSize;
        return result;
    }
}

int LZ4_saveDict(LZ4_cstream* dict, char* safeBuffer, int dictSize)
{
    if (dictSize > 64 * KB) dictSize = 64 * KB;
    if (dictSize < 4) dictSize = 0;
    if (dictSize > (int)dict->dictSize) dictSize = (int)dict->dictSize;

    if (dictSize > 0) {
        const BYTE* const previousDictEnd = dict->dictionary + dict->dictSize;
        memmove(safeBuffer, previousDictEnd - dictSize, (size_t)dictSize);
    }

    dict->dictionary = (const BYTE*)safeBuffer;
    dict->dictSize = (U32)dictSize;
    return dictSize;
}

/* ---------------------------------------------------------------- *
 *  Decompression
 * ---------------------------------------------------------------- */

static int decompress_generic(const char* const src, char* const dst,
                              int srcSize, int outputSize,
                              const BYTE* const dictStart, const size_t dictSize)
{
    const BYTE* ip = (const BYTE*)src;
    const BYTE* const iend = ip + srcSize;

    BYTE* op = (BYTE*)dst;
    BYTE* const oend = op + outputSize;
    BYTE* cpy;

    const BYTE* const dictEnd = (dictStart == NULL) ? NULL : dictStart + dictSize;
    const BYTE* const lowPrefix = (const BYTE*)dst;

    if (srcSize == 0) return -1;
    if (outputSize == 0) return (srcSize == 1 && *ip == 0) ? 0 : -1;

    while (1) {
        unsigned token;
        size_t length;
        const BYTE* match;
        size_t offset;

        token = *ip++;
        length = token >> ML_BITS;

        if (length == RUN_MASK) {
            unsigned s;
            do {
                if (ip >= iend) return -1;
                s = *ip++;
                length += s;
            } while (s == 255);
            if (length > (size_t)(oend - op)) return -1;
            if (length > (size_t)(iend - ip)) return -1;
        }

        /* copy literals */
        if ((size_t)(iend - ip) < length) return -1;
        if ((size_t)(oend - op) < length) return -1;
        memmove(op, ip, length);
        ip += length;
        op += length;

        if (ip == iend) {
            /* end of block: must terminate with a literal run */
            break;
        }
        if ((size_t)(iend - ip) < 2) return -1;

        offset = rd16(ip);
        ip += 2;
        match = op - offset;

        length = token & ML_MASK;
        if (length == ML_MASK) {
            unsigned s;
            do {
                if (ip >= iend) return -1;
                s = *ip++;
                length += s;
            } while (s == 255);
        }
        length += MINMATCH;

        if (offset == 0) return -1;
        if (match < lowPrefix) {
            size_t const fromDict = (size_t)(lowPrefix - match);
            size_t copySize;
            if (dictStart == NULL || fromDict > dictSize) return -1;
            if (length > (size_t)(oend - op)) return -1;
            copySize = fromDict < length ? fromDict : length;
            memcpy(op, dictEnd - fromDict, copySize);
            op += copySize;
            length -= copySize;
            if (length > 0) {
                /* remainder comes from the current prefix, starting at dst */
                const BYTE* m2 = lowPrefix;
                while (length--) *op++ = *m2++;
            }
            continue;
        }

        if (length > (size_t)(oend - op)) return -1;
        cpy = op + length;
        if (offset >= 8) {
            memmove(op, match, length);
            op = cpy;
        } else {
            while (op < cpy) *op++ = *match++;
        }
    }

    if (ip != iend) return -1;
    return (int)(op - (BYTE*)dst);
}

int LZ4_decompress_safe(const char* src, char* dst, int cSize, int dstCapacity)
{
    return decompress_generic(src, dst, cSize, dstCapacity, NULL, 0);
}

int LZ4_decompress_safe_usingDict(const char* src, char* dst, int cSize, int dstCapacity,
                                  const char* dictStart, int dictSize)
{
    if (dictSize == 0 || dictStart == NULL)
        return decompress_generic(src, dst, cSize, dstCapacity, NULL, 0);
    if (dictStart + dictSize == dst) {
        /* prefix: history is contiguous with the output buffer */
        return decompress_generic(src, dst, cSize, dstCapacity,
                                  (const BYTE*)dictStart, (size_t)dictSize);
    }
    return decompress_generic(src, dst, cSize, dstCapacity,
                              (const BYTE*)dictStart, (size_t)dictSize);
}

