                     | ((c->prefs.blockIndep ? 1 : 0) << 5)
                     | ((c->prefs.blockChecksum ? 1 : 0) << 4)
                     | ((c->prefs.contentSize > 0 ? 1 : 0) << 3)
                     | ((c->prefs.contentChecksum ? 1 : 0) << 2)
                     | (c->prefs.dictID ? 1 : 0));
