size_t LZ4F_compressUpdate(LZ4F_cctx* c, void* dst, size_t dstCapacity,
                           const void* src, size_t srcSize)
{
    const uint8_t* srcPtr = (const uint8_t*)src;
    const uint8_t* const srcEnd = srcPtr + srcSize;
    uint8_t* dstPtr = (uint8_t*)dst;

    (void)dstCapacity;
    if (c->prefs.contentChecksum) XH32_update(&c->xxh, src, srcSize);
    c->totalIn += srcSize;

    if (c->tmpInSize > 0) {
        size_t const sizeToCopy = c->blockSize - c->tmpInSize;
        if (sizeToCopy > srcSize) {
            memcpy(c->tmpIn + c->tmpInSize, srcPtr, srcSize);
            c->tmpInSize += srcSize;
            return 0;
        }
        memcpy(c->tmpIn + c->tmpInSize, srcPtr, sizeToCopy);
        srcPtr += sizeToCopy;
        dstPtr += makeBlock(c, dstPtr, c->tmpIn, c->blockSize);
        c->tmpInSize = 0;
        c->lastBlockFromSrc = 0;
    }

    while ((size_t)(srcEnd - srcPtr) >= c->blockSize) {
        dstPtr += makeBlock(c, dstPtr, srcPtr, c->blockSize);
        srcPtr += c->blockSize;
        c->lastBlockFromSrc = 1;
    }

    if (srcPtr < srcEnd) {
        dstPtr += makeBlock(c, dstPtr, srcPtr, (size_t)(srcEnd - srcPtr));
