size_t LZ4F_compressEnd(LZ4F_cctx* c, void* dst, size_t dstCapacity)
{
    uint8_t* dstPtr = (uint8_t*)dst;

    (void)dstCapacity;
    if (c->tmpInSize > 0) {
        dstPtr += makeBlock(c, dstPtr, c->tmpIn, c->tmpInSize);
        c->tmpInSize = 0;
    }
    wrLE32(dstPtr, 0);
    dstPtr += 4;
    if (c->prefs.contentChecksum) {
        wrLE32(dstPtr, XH32_digest(&c->xxh));
        dstPtr += 4;
    }
    return (size_t)(dstPtr - (uint8_t*)dst);
}

size_t LZ4F_compressFrame(void* dst, size_t dstCapacity, const void* src, size_t srcSize,
                          const LZ4F_prefs* prefs, const void* dict, size_t dictSize)
{
    LZ4F_prefs p = *prefs;
    LZ4F_cctx* c = LZ4F_createCCtx();
    uint8_t* out = (uint8_t*)dst;
    size_t n = 0;

    if (!c) return 0;
    if (p.contentSize != 0) p.contentSize = (uint64_t)srcSize;
    p.blockSizeID = LZ4F_optimalBSID(p.blockSizeID, srcSize);
    if (srcSize <= LZ4F_blockSizeFromID(p.blockSizeID)) p.blockIndep = 1;

    LZ4F_setCDict(c, dict, dictSize);
    n += LZ4F_compressBegin(c, out + n, dstCapacity - n, &p);
    if (srcSize > 0) n += LZ4F_compressUpdate(c, out + n, dstCapacity - n, src, srcSize);
    n += LZ4F_compressEnd(c, out + n, dstCapacity - n);
    LZ4F_freeCCtx(c);
    return n;
}

void wrLE16_unused(void* p, uint16_t v) { wrLE16(p, v); }

