/* lz4frame.c - LZ4 frame format writer. */
#include "lz4frame.h"
#include "lz4blk.h"
#include "lz4hc.h"
#include "xxh32.h"
#include <stdlib.h>
#include <string.h>

#define KB 1024
#define BHSIZE 4
#define BFSIZE 4
#define LZ4F_BLOCKUNCOMPRESSED_FLAG 0x80000000U

size_t LZ4F_blockSizeFromID(int id)
{
    switch (id) {
    case 4: return 64 * KB;
    case 5: return 256 * KB;
    case 6: return 1024 * KB;
    default: return 4096 * KB;
    }
}

int LZ4F_optimalBSID(int requestedBSID, size_t srcSize)
{
    int proposedBSID = 4;
    size_t maxBlockSize = 64 * KB;
    while (requestedBSID > proposedBSID) {
        if (srcSize <= maxBlockSize) return proposedBSID;
        proposedBSID++;
        maxBlockSize <<= 2;
    }
    return requestedBSID;
}

struct LZ4F_cctx_s {
    LZ4F_prefs prefs;
    size_t blockSize;
    LZ4_cstream* fast;
    LZ4_streamHC* hc;
    uint8_t* tmpBuff;      /* dictionary storage for linked-block mode */
    size_t tmpBuffSize;
    uint8_t* tmpIn;
    size_t tmpInSize;
    XH32_state xxh;
    uint64_t totalIn;
    int lastBlockFromSrc;
    const void* cdict;
    size_t cdictSize;
    int started;
};

static void wrLE16(void* p, uint16_t v) { uint8_t* d = (uint8_t*)p; d[0] = (uint8_t)v; d[1] = (uint8_t)(v >> 8); }
static void wrLE32(void* p, uint32_t v)
{
    uint8_t* d = (uint8_t*)p;
    d[0] = (uint8_t)v; d[1] = (uint8_t)(v >> 8); d[2] = (uint8_t)(v >> 16); d[3] = (uint8_t)(v >> 24);
}
static void wrLE64(void* p, uint64_t v)
{
    wrLE32(p, (uint32_t)v);
    wrLE32((uint8_t*)p + 4, (uint32_t)(v >> 32));
}

LZ4F_cctx* LZ4F_createCCtx(void)
{
    LZ4F_cctx* c = (LZ4F_cctx*)calloc(1, sizeof(*c));
    if (!c) return NULL;
    c->fast = (LZ4_cstream*)malloc(sizeof(LZ4_cstream));
    c->hc = (LZ4_streamHC*)malloc(sizeof(LZ4_streamHC));
    if (!c->fast || !c->hc) { LZ4F_freeCCtx(c); return NULL; }
    LZ4_initStream(c->fast);
    LZ4_initStreamHC(c->hc);
    return c;
}

void LZ4F_freeCCtx(LZ4F_cctx* c)
{
    if (!c) return;
    free(c->fast);
    free(c->hc);
    free(c->tmpBuff);
    free(c);
}

void LZ4F_setCDict(LZ4F_cctx* c, const void* dict, size_t dictSize)
{
    c->cdict = dict;
    c->cdictSize = dictSize;
}

size_t LZ4F_compressBound(size_t srcSize, const LZ4F_prefs* prefs)
{
    size_t const blockSize = LZ4F_blockSizeFromID(prefs ? prefs->blockSizeID : 7);
    size_t const nbBlocks = (srcSize / blockSize) + 2;
    size_t const blockOverhead = BHSIZE + (prefs && prefs->blockChecksum ? BFSIZE : 0);
    return srcSize + nbBlocks * (blockSize > 0 ? blockOverhead : 0) + blockSize + 64;
}

/* --------------------------------------------------------------- */

static int hcLevel(int level) { return level < LZ4HC_CLEVEL_MIN ? 0 : 1; }

static size_t compressOneBlock(LZ4F_cctx* c, uint8_t* dst, const uint8_t* src, size_t srcSize)
