/* lz4hc.c - LZ4 high compression mode (hash chain + optimal parser). */
#include "lz4hc.h"
#include "lz4blk.h"
#include <stdlib.h>
#include <string.h>

#define MINMATCH 4
#define WILDCOPYLENGTH 8
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_minLength (MFLIMIT + 1)
#define ML_BITS 4
#define ML_MASK ((1u << ML_BITS) - 1)
#define RUN_BITS (8 - ML_BITS)
#define RUN_MASK ((1u << RUN_BITS) - 1)
#define OPTIMAL_ML (int)((ML_MASK - 1) + MINMATCH)
#define LZ4_OPT_NUM (1 << 12)
#define TRAILING_LITERALS 3
#define KB 1024
#define MB (1024 * KB)
#define GB (1024u * MB)
#define LZ4HC_HASHSIZE 4

typedef uint8_t BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;
typedef size_t reg_t;

enum { notLimited = 0, limitedOutput = 1 };
enum { favorCompressionRatio = 0, favorDecompressionSpeed };

#define DELTANEXTU16(table, pos) table[(U16)(pos)]
#define MAXI(a, b) ((a) > (b) ? (a) : (b))
#define MINI(a, b) ((a) < (b) ? (a) : (b))

static U16 rd16(const void* p) { U16 v; memcpy(&v, p, 2); return v; }
static U32 rd32(const void* p) { U32 v; memcpy(&v, p, 4); return v; }
static U64 rd64(const void* p) { U64 v; memcpy(&v, p, 8); return v; }
static void wr16(void* p, U16 v) { memcpy(p, &v, 2); }

static unsigned nbCommonBytes(U64 v) { return (unsigned)(__builtin_ctzll(v) >> 3); }

static unsigned countMatch(const BYTE* pIn, const BYTE* pMatch, const BYTE* pInLimit)
{
    const BYTE* const pStart = pIn;
    if (pIn < pInLimit - 7) {
        U64 const diff = rd64(pMatch) ^ rd64(pIn);
        if (!diff) { pIn += 8; pMatch += 8; }
        else return nbCommonBytes(diff);
    }
    while (pIn < pInLimit - 7) {
        U64 const diff = rd64(pMatch) ^ rd64(pIn);
        if (!diff) { pIn += 8; pMatch += 8; continue; }
        pIn += nbCommonBytes(diff);
        return (unsigned)(pIn - pStart);
    }
    if ((pIn < (pInLimit - 3)) && (rd32(pMatch) == rd32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < (pInLimit - 1)) && (rd16(pMatch) == rd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

static void wildCopy8(void* dstPtr, const void* srcPtr, void* dstEnd)
{
    BYTE* d = (BYTE*)dstPtr;
    const BYTE* s = (const BYTE*)srcPtr;
    BYTE* const e = (BYTE*)dstEnd;
    if (d >= e) return;
    do { memcpy(d, s, 8); d += 8; s += 8; } while (d < e);
}

static U32 hashPtr(const void* ptr)
{
    return (rd32(ptr) * 2654435761U) >> ((MINMATCH * 8) - LZ4HC_HASH_LOG);
}

static void clearTables(LZ4_streamHC* hc4)
{
    memset(hc4->hashTable, 0, sizeof(hc4->hashTable));
    memset(hc4->chainTable, 0xFF, sizeof(hc4->chainTable));
}

static void initInternal(LZ4_streamHC* hc4, const BYTE* start)
{
    size_t const bufferSize = (size_t)(hc4->end - hc4->prefixStart);
    size_t newStartingOffset = bufferSize + hc4->dictLimit;
    if (newStartingOffset > 1 * GB) {
        clearTables(hc4);
        newStartingOffset = 0;
    }
    newStartingOffset += 64 * KB;
    hc4->nextToUpdate = (U32)newStartingOffset;
    hc4->prefixStart = start;
    hc4->end = start;
    hc4->dictStart = start;
    hc4->dictLimit = (U32)newStartingOffset;
    hc4->lowLimit = (U32)newStartingOffset;
}

static void hcInsert(LZ4_streamHC* hc4, const BYTE* ip)
{
    U16* const chainTable = hc4->chainTable;
    U32* const hashTable = hc4->hashTable;
    const BYTE* const prefixPtr = hc4->prefixStart;
    U32 const prefixIdx = hc4->dictLimit;
    U32 const target = (U32)(ip - prefixPtr) + prefixIdx;
    U32 idx = hc4->nextToUpdate;

    while (idx < target) {
        U32 const h = hashPtr(prefixPtr + idx - prefixIdx);
        size_t delta = idx - hashTable[h];
        if (delta > LZ4_DISTANCE_MAX) delta = LZ4_DISTANCE_MAX;
        DELTANEXTU16(chainTable, idx) = (U16)delta;
        hashTable[h] = idx;
        idx++;
    }
    hc4->nextToUpdate = target;
}

static int countBack(const BYTE* const ip, const BYTE* const match,
                     const BYTE* const iMin, const BYTE* const mMin)
{
    int back = 0;
    int const min = (int)MAXI(iMin - ip, mMin - match);
    while ((back > min) && (ip[back - 1] == match[back - 1])) back--;
    return back;
}

static unsigned countPattern(const BYTE* ip, const BYTE* const iEnd, U32 const pattern32)
{
    const BYTE* const iStart = ip;
    U64 const pattern = (U64)pattern32 + (((U64)pattern32) << 32);

    while (ip < iEnd - 7) {
        U64 const diff = rd64(ip) ^ pattern;
        if (!diff) { ip += 8; continue; }
        ip += nbCommonBytes(diff);
        return (unsigned)(ip - iStart);
    }
    {   U64 patternByte = pattern;
        while ((ip < iEnd) && (*ip == (BYTE)patternByte)) { ip++; patternByte >>= 8; }
    }
    return (unsigned)(ip - iStart);
}

static unsigned reverseCountPattern(const BYTE* ip, const BYTE* const iLow, U32 pattern)
{
    const BYTE* const iStart = ip;

    while (ip >= iLow + 4) {
        if (rd32(ip - 4) != pattern) break;
        ip -= 4;
    }
    {   const BYTE* bytePtr = (const BYTE*)(&pattern) + 3;
        while (ip > iLow) {
            if (ip[-1] != *bytePtr) break;
            ip--; bytePtr--;
        }
    }
    return (unsigned)(iStart - ip);
}

static U32 rotl32(U32 x, int r) { return ((x << r) | (x >> (32 - r))); }

static U32 rotatePattern(size_t const rotate, U32 const pattern)
{
    size_t const bitsToRotate = (rotate & (sizeof(pattern) - 1)) << 3;
    if (bitsToRotate == 0) return pattern;
    return rotl32(pattern, (int)bitsToRotate);
}

static int protectDictEnd(U32 const dictLimit, U32 const matchIndex)
{
    return ((U32)((dictLimit - 1) - matchIndex) >= 3);
}

typedef enum { rep_untested, rep_not, rep_confirmed } repeat_state_e;

static int insertAndGetWiderMatch(
        LZ4_streamHC* const hc4,
        const BYTE* const ip,
        const BYTE* const iLowLimit, const BYTE* const iHighLimit,
        int longest,
        const BYTE** matchpos,
        const BYTE** startpos,
        const int maxNbAttempts,
        const int patternAnalysis, const int chainSwap,
        const int favorDecSpeed)
{
    U16* const chainTable = hc4->chainTable;
    U32* const hashTable = hc4->hashTable;
    const BYTE* const prefixPtr = hc4->prefixStart;
    const U32 prefixIdx = hc4->dictLimit;
    const U32 ipIndex = (U32)(ip - prefixPtr) + prefixIdx;
    const int withinStartDistance = (hc4->lowLimit + (LZ4_DISTANCE_MAX + 1) > ipIndex);
    const U32 lowestMatchIndex = (withinStartDistance) ? hc4->lowLimit : ipIndex - LZ4_DISTANCE_MAX;
    const BYTE* const dictStart = hc4->dictStart;
    const U32 dictIdx = hc4->lowLimit;
    const BYTE* const dictEnd = dictStart + prefixIdx - dictIdx;
    int const lookBackLength = (int)(ip - iLowLimit);
    int nbAttempts = maxNbAttempts;
    U32 matchChainPos = 0;
    U32 const pattern = rd32(ip);
    U32 matchIndex;
    repeat_state_e repeat = rep_untested;
    size_t srcPatternLength = 0;

    hcInsert(hc4, ip);
    matchIndex = hashTable[hashPtr(ip)];

    while ((matchIndex >= lowestMatchIndex) && (nbAttempts > 0)) {
        int matchLength = 0;
        nbAttempts--;
        if (favorDecSpeed && (ipIndex - matchIndex < 8)) {
            /* skipped */
        } else if (matchIndex >= prefixIdx) {
            const BYTE* const matchPtr = prefixPtr + (matchIndex - prefixIdx);
            if (rd16(iLowLimit + longest - 1) == rd16(matchPtr - lookBackLength + longest - 1)) {
                if (rd32(matchPtr) == pattern) {
                    int const back = lookBackLength ? countBack(ip, matchPtr, iLowLimit, prefixPtr) : 0;
                    matchLength = MINMATCH + (int)countMatch(ip + MINMATCH, matchPtr + MINMATCH, iHighLimit);
                    matchLength -= back;
                    if (matchLength > longest) {
                        longest = matchLength;
                        *matchpos = matchPtr + back;
                        *startpos = ip + back;
                    }
                }
            }
        } else {
            const BYTE* const matchPtr = dictStart + (matchIndex - dictIdx);
            if ((matchIndex <= prefixIdx - 4) && (rd32(matchPtr) == pattern)) {
                int back = 0;
                const BYTE* vLimit = ip + (prefixIdx - matchIndex);
                if (vLimit > iHighLimit) vLimit = iHighLimit;
                matchLength = (int)countMatch(ip + MINMATCH, matchPtr + MINMATCH, vLimit) + MINMATCH;
                if ((ip + matchLength == vLimit) && (vLimit < iHighLimit))
                    matchLength += (int)countMatch(ip + matchLength, prefixPtr, iHighLimit);
                back = lookBackLength ? countBack(ip, matchPtr, iLowLimit, dictStart) : 0;
                matchLength -= back;
                if (matchLength > longest) {
                    longest = matchLength;
                    *matchpos = prefixPtr - prefixIdx + matchIndex + back;
                    *startpos = ip + back;
                }
            }
        }

        if (chainSwap && matchLength == longest) {
            if (matchIndex + (U32)longest <= ipIndex) {
                int const kTrigger = 4;
                U32 distanceToNextMatch = 1;
                int const end = longest - MINMATCH + 1;
                int step = 1;
                int accel = 1 << kTrigger;
                int pos;
                for (pos = 0; pos < end; pos += step) {
                    U32 const candidateDist = DELTANEXTU16(chainTable, matchIndex + (U32)pos);
                    step = (accel++ >> kTrigger);
                    if (candidateDist > distanceToNextMatch) {
                        distanceToNextMatch = candidateDist;
                        matchChainPos = (U32)pos;
                        accel = 1 << kTrigger;
                    }
                }
                if (distanceToNextMatch > 1) {
                    if (distanceToNextMatch > matchIndex) break;
                    matchIndex -= distanceToNextMatch;
                    continue;
                }
            }
        }

        {   U32 const distNextMatch = DELTANEXTU16(chainTable, matchIndex);
            if (patternAnalysis && distNextMatch == 1 && matchChainPos == 0) {
                U32 const matchCandidateIdx = matchIndex - 1;
                if (repeat == rep_untested) {
                    if (((pattern & 0xFFFF) == (pattern >> 16))
                        & ((pattern & 0xFF) == (pattern >> 24))) {
                        repeat = rep_confirmed;
                        srcPatternLength = countPattern(ip + 4, iHighLimit, pattern) + 4;
                    } else {
                        repeat = rep_not;
                    }
                }
                if ((repeat == rep_confirmed) && (matchCandidateIdx >= lowestMatchIndex)
                    && protectDictEnd(prefixIdx, matchCandidateIdx)) {
                    const int extDict = matchCandidateIdx < prefixIdx;
                    const BYTE* const matchPtr = extDict ? dictStart + (matchCandidateIdx - dictIdx)
                                                         : prefixPtr + (matchCandidateIdx - prefixIdx);
                    if (rd32(matchPtr) == pattern) {
                        const BYTE* const iLimit = extDict ? dictEnd : iHighLimit;
                        size_t forwardPatternLength = countPattern(matchPtr + 4, iLimit, pattern) + 4;
                        if (extDict && matchPtr + forwardPatternLength == iLimit) {
                            U32 const rotatedPattern = rotatePattern(forwardPatternLength, pattern);
                            forwardPatternLength += countPattern(prefixPtr, iHighLimit, rotatedPattern);
                        }
                        {   const BYTE* const lowestMatchPtr = extDict ? dictStart : prefixPtr;
                            size_t backLength = reverseCountPattern(matchPtr, lowestMatchPtr, pattern);
                            size_t currentSegmentLength;
                            if (!extDict && matchPtr - backLength == prefixPtr && dictIdx < prefixIdx) {
                                U32 const rotatedPattern = rotatePattern((U32)(-(int)backLength), pattern);
                                backLength += reverseCountPattern(dictEnd, dictStart, rotatedPattern);
                            }
                            backLength = matchCandidateIdx - MAXI(matchCandidateIdx - (U32)backLength, lowestMatchIndex);
                            currentSegmentLength = backLength + forwardPatternLength;

                            if ((currentSegmentLength >= srcPatternLength)
                                && (forwardPatternLength <= srcPatternLength)) {
                                U32 const newMatchIndex = matchCandidateIdx + (U32)forwardPatternLength - (U32)srcPatternLength;
                                if (protectDictEnd(prefixIdx, newMatchIndex)) matchIndex = newMatchIndex;
                                else matchIndex = prefixIdx;
                            } else {
                                U32 const newMatchIndex = matchCandidateIdx - (U32)backLength;
                                if (!protectDictEnd(prefixIdx, newMatchIndex)) {
                                    matchIndex = prefixIdx;
                                } else {
                                    matchIndex = newMatchIndex;
                                    if (lookBackLength == 0) {
                                        size_t const maxML = MINI(currentSegmentLength, srcPatternLength);
                                        if ((size_t)longest < maxML) {
                                            if ((size_t)(ip - prefixPtr) + prefixIdx - matchIndex > LZ4_DISTANCE_MAX) break;
                                            longest = (int)maxML;
                                            *matchpos = prefixPtr - prefixIdx + matchIndex;
                                            *startpos = ip;
                                        }
                                        {   U32 const distToNextPattern = DELTANEXTU16(chainTable, matchIndex);
                                            if (distToNextPattern > matchIndex) break;
                                            matchIndex -= distToNextPattern;
                                        }
                                    }
                                }
                            }
                        }
                        continue;
                    }
                }
            }
        }

        matchIndex -= DELTANEXTU16(chainTable, matchIndex + matchChainPos);
    }

    return longest;
}

static int insertAndFindBestMatch(LZ4_streamHC* const hc4,
                                  const BYTE* const ip, const BYTE* const iLimit,
                                  const BYTE** matchpos,
                                  const int maxNbAttempts,
                                  const int patternAnalysis)
{
    const BYTE* uselessPtr = ip;
    return insertAndGetWiderMatch(hc4, ip, ip, iLimit, MINMATCH - 1, matchpos, &uselessPtr,
                                  maxNbAttempts, patternAnalysis, 0, favorCompressionRatio);
}

static int encodeSequence(const BYTE** _ip, BYTE** _op, const BYTE** _anchor,
                          int matchLength, const BYTE* const match,
                          int limit, BYTE* oend)
{
#define ip (*_ip)
#define op (*_op)
#define anchor (*_anchor)
    size_t length;
    BYTE* const token = (op)++;

    length = (size_t)(ip - anchor);
    if ((limit) && ((op + (length / 255) + length + (2 + 1 + LASTLITERALS)) > oend)) return 1;
    if (length >= RUN_MASK) {
        size_t len = length - RUN_MASK;
        *token = (BYTE)(RUN_MASK << ML_BITS);
        for (; len >= 255; len -= 255) *(op)++ = 255;
        *(op)++ = (BYTE)len;
    } else {
        *token = (BYTE)(length << ML_BITS);
    }

    wildCopy8(op, anchor, op + length);
    op += length;

    wr16(op, (U16)(ip - match));
    op += 2;

    length = (size_t)matchLength - MINMATCH;
    if ((limit) && (op + (length / 255) + (1 + LASTLITERALS) > oend)) return 1;
    if (length >= ML_MASK) {
        *token += (BYTE)ML_MASK;
        length -= ML_MASK;
        for (; length >= 510; length -= 510) { *(op)++ = 255; *(op)++ = 255; }
        if (length >= 255) { length -= 255; *(op)++ = 255; }
        *(op)++ = (BYTE)length;
    } else {
        *token += (BYTE)length;
    }

    ip += matchLength;
    anchor = ip;
    return 0;
#undef ip
#undef op
#undef anchor
}

#define UPD(i, o, a) &i, &o, &a

static int compressHashChain(LZ4_streamHC* const ctx,
                             const char* const source, char* const dest,
                             int* srcSizePtr, int const maxOutputSize,
                             int maxNbAttempts, int const limit)
{
    const int inputSize = *srcSizePtr;
    const int patternAnalysis = (maxNbAttempts > 128);

    const BYTE* ip = (const BYTE*)source;
    const BYTE* anchor = ip;
    const BYTE* const iend = ip + inputSize;
    const BYTE* const mflimit = iend - MFLIMIT;
    const BYTE* const matchlimit = (iend - LASTLITERALS);

    BYTE* op = (BYTE*)dest;
    BYTE* oend = op + maxOutputSize;

    int ml0, ml, ml2, ml3;
    const BYTE* start0;
    const BYTE* ref0;
    const BYTE* ref = NULL;
    const BYTE* start2 = NULL;
    const BYTE* ref2 = NULL;
    const BYTE* start3 = NULL;
    const BYTE* ref3 = NULL;

    *srcSizePtr = 0;
    if (inputSize < LZ4_minLength) goto _last_literals;

    while (ip <= mflimit) {
        ml = insertAndFindBestMatch(ctx, ip, matchlimit, &ref, maxNbAttempts, patternAnalysis);
        if (ml < MINMATCH) { ip++; continue; }

        start0 = ip; ref0 = ref; ml0 = ml;

_Search2:
        if (ip + ml <= mflimit) {
            ml2 = insertAndGetWiderMatch(ctx, ip + ml - 2, ip + 0, matchlimit, ml, &ref2, &start2,
                                         maxNbAttempts, patternAnalysis, 0, favorCompressionRatio);
        } else {
            ml2 = ml;
        }

        if (ml2 == ml) {
            if (encodeSequence(UPD(ip, op, anchor), ml, ref, limit, oend)) return 0;
            continue;
        }

        if (start0 < ip) {
            if (start2 < ip + ml0) { ip = start0; ref = ref0; ml = ml0; }
        }

        if ((start2 - ip) < 3) {
            ml = ml2;
            ip = start2;
            ref = ref2;
            goto _Search2;
        }

_Search3:
        if ((start2 - ip) < OPTIMAL_ML) {
            int correction;
            int new_ml = ml;
            if (new_ml > OPTIMAL_ML) new_ml = OPTIMAL_ML;
            if (ip + new_ml > start2 + ml2 - MINMATCH) new_ml = (int)(start2 - ip) + ml2 - MINMATCH;
            correction = new_ml - (int)(start2 - ip);
            if (correction > 0) {
                start2 += correction;
                ref2 += correction;
                ml2 -= correction;
            }
        }

        if (start2 + ml2 <= mflimit) {
            ml3 = insertAndGetWiderMatch(ctx, start2 + ml2 - 3, start2, matchlimit, ml2, &ref3, &start3,
                                         maxNbAttempts, patternAnalysis, 0, favorCompressionRatio);
        } else {
            ml3 = ml2;
        }

        if (ml3 == ml2) {
            if (start2 < ip + ml) ml = (int)(start2 - ip);
            if (encodeSequence(UPD(ip, op, anchor), ml, ref, limit, oend)) return 0;
            ip = start2;
            if (encodeSequence(UPD(ip, op, anchor), ml2, ref2, limit, oend)) return 0;
            continue;
        }

        if (start3 < ip + ml + 3) {
            if (start3 >= (ip + ml)) {
                if (start2 < ip + ml) {
                    int correction = (int)(ip + ml - start2);
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                    if (ml2 < MINMATCH) {
                        start2 = start3;
                        ref2 = ref3;
                        ml2 = ml3;
                    }
                }
                if (encodeSequence(UPD(ip, op, anchor), ml, ref, limit, oend)) return 0;
                ip = start3;
                ref = ref3;
                ml = ml3;

                start0 = start2;
                ref0 = ref2;
                ml0 = ml2;
                goto _Search2;
            }
            start2 = start3;
            ref2 = ref3;
            ml2 = ml3;
            goto _Search3;
        }

        if (start2 < ip + ml) {
            if ((start2 - ip) < OPTIMAL_ML) {
                int correction;
                if (ml > OPTIMAL_ML) ml = OPTIMAL_ML;
                if (ip + ml > start2 + ml2 - MINMATCH) ml = (int)(start2 - ip) + ml2 - MINMATCH;
                correction = ml - (int)(start2 - ip);
                if (correction > 0) {
                    start2 += correction;
                    ref2 += correction;
                    ml2 -= correction;
                }
            } else {
                ml = (int)(start2 - ip);
            }
        }
        if (encodeSequence(UPD(ip, op, anchor), ml, ref, limit, oend)) return 0;

        ip = start2; ref = ref2; ml = ml2;
        start2 = start3; ref2 = ref3; ml2 = ml3;
        goto _Search3;
    }

_last_literals:
    {   size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit && (op + totalSize > oend)) return 0;
        ip = anchor + lastRunSize;

        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }

    *srcSizePtr = (int)(((const char*)ip) - source);
    return (int)(((char*)op) - dest);
}

/* ------------------------- optimal parser ------------------------- */

typedef struct { int price; int off; int mlen; int litlen; } optimal_t;
typedef struct { int off; int len; } hcmatch_t;

static int literalsPrice(int const litlen)
{
    int price = litlen;
    if (litlen >= (int)RUN_MASK) price += 1 + ((litlen - (int)RUN_MASK) / 255);
    return price;
}

static int sequencePrice(int litlen, int mlen)
{
    int price = 1 + 2;
    price += literalsPrice(litlen);
    if (mlen >= (int)(ML_MASK + MINMATCH)) price += 1 + ((mlen - (int)(ML_MASK + MINMATCH)) / 255);
    return price;
}

static hcmatch_t findLongerMatch(LZ4_streamHC* const ctx,
                                 const BYTE* ip, const BYTE* const iHighLimit,
                                 int minLen, int nbSearches, const int favorDecSpeed)
{
    hcmatch_t match = { 0, 0 };
    const BYTE* matchPtr = NULL;
    int matchLength = insertAndGetWiderMatch(ctx, ip, ip, iHighLimit, minLen, &matchPtr, &ip,
                                             nbSearches, 1, 1, favorDecSpeed);
    if (matchLength <= minLen) return match;
    if (favorDecSpeed) {
        if ((matchLength > 18) & (matchLength <= 36)) matchLength = 18;
    }
    match.len = matchLength;
    match.off = (int)(ip - matchPtr);
    return match;
}

static int compressOptimal(LZ4_streamHC* ctx,
                           const char* const source, char* dst,
                           int* srcSizePtr, int dstCapacity,
                           int const nbSearches, size_t sufficient_len,
                           const int limit, int const fullUpdate,
                           const int favorDecSpeed)
{
    int retval = 0;
    optimal_t* const opt = (optimal_t*)malloc(sizeof(optimal_t) * (LZ4_OPT_NUM + TRAILING_LITERALS));

    const BYTE* ip = (const BYTE*)source;
    const BYTE* anchor = ip;
    const BYTE* const iend = ip + *srcSizePtr;
    const BYTE* const mflimit = iend - MFLIMIT;
    const BYTE* const matchlimit = iend - LASTLITERALS;
    BYTE* op = (BYTE*)dst;
    BYTE* oend = op + dstCapacity;

    if (opt == NULL) goto _return_label;
    *srcSizePtr = 0;
    if (sufficient_len >= LZ4_OPT_NUM) sufficient_len = LZ4_OPT_NUM - 1;

    while (ip <= mflimit) {
        int const llen = (int)(ip - anchor);
        int best_mlen, best_off;
        int cur, last_match_pos = 0;

        hcmatch_t const firstMatch = findLongerMatch(ctx, ip, matchlimit, MINMATCH - 1, nbSearches, favorDecSpeed);
        if (firstMatch.len == 0) { ip++; continue; }

        if ((size_t)firstMatch.len > sufficient_len) {
            int const firstML = firstMatch.len;
            const BYTE* const matchPos = ip - firstMatch.off;
            if (encodeSequence(UPD(ip, op, anchor), firstML, matchPos, limit, oend)) goto _return_label;
            continue;
        }

        {   int rPos;
            for (rPos = 0; rPos < MINMATCH; rPos++) {
                int const cost = literalsPrice(llen + rPos);
                opt[rPos].mlen = 1;
                opt[rPos].off = 0;
                opt[rPos].litlen = llen + rPos;
                opt[rPos].price = cost;
            }
        }
        {   int mlen = MINMATCH;
            int const matchML = firstMatch.len;
            int const offset = firstMatch.off;
            for (; mlen <= matchML; mlen++) {
                int const cost = sequencePrice(llen, mlen);
                opt[mlen].mlen = mlen;
                opt[mlen].off = offset;
                opt[mlen].litlen = llen;
                opt[mlen].price = cost;
            }
        }
        last_match_pos = firstMatch.len;
        {   int addLit;
            for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                opt[last_match_pos + addLit].mlen = 1;
                opt[last_match_pos + addLit].off = 0;
                opt[last_match_pos + addLit].litlen = addLit;
                opt[last_match_pos + addLit].price = opt[last_match_pos].price + literalsPrice(addLit);
            }
        }

        for (cur = 1; cur < last_match_pos; cur++) {
            const BYTE* const curPtr = ip + cur;
            hcmatch_t newMatch;

            if (curPtr > mflimit) break;
            if (fullUpdate) {
                if ((opt[cur + 1].price <= opt[cur].price)
                    && (opt[cur + MINMATCH].price < opt[cur].price + 3))
                    continue;
            } else {
                if (opt[cur + 1].price <= opt[cur].price) continue;
            }

            if (fullUpdate)
                newMatch = findLongerMatch(ctx, curPtr, matchlimit, MINMATCH - 1, nbSearches, favorDecSpeed);
            else
                newMatch = findLongerMatch(ctx, curPtr, matchlimit, last_match_pos - cur, nbSearches, favorDecSpeed);
            if (!newMatch.len) continue;

            if (((size_t)newMatch.len > sufficient_len) || (newMatch.len + cur >= LZ4_OPT_NUM)) {
                best_mlen = newMatch.len;
                best_off = newMatch.off;
                last_match_pos = cur + 1;
                goto encode;
            }

            {   int const baseLitlen = opt[cur].litlen;
                int litlen;
                for (litlen = 1; litlen < MINMATCH; litlen++) {
                    int const price = opt[cur].price - literalsPrice(baseLitlen) + literalsPrice(baseLitlen + litlen);
                    int const pos = cur + litlen;
                    if (price < opt[pos].price) {
                        opt[pos].mlen = 1;
                        opt[pos].off = 0;
                        opt[pos].litlen = baseLitlen + litlen;
                        opt[pos].price = price;
                    }
                }
            }

            {   int const matchML = newMatch.len;
                int ml = MINMATCH;
                for (; ml <= matchML; ml++) {
                    int const pos = cur + ml;
                    int const offset = newMatch.off;
                    int price;
                    int ll;
                    if (opt[cur].mlen == 1) {
                        ll = opt[cur].litlen;
                        price = ((cur > ll) ? opt[cur - ll].price : 0) + sequencePrice(ll, ml);
                    } else {
                        ll = 0;
                        price = opt[cur].price + sequencePrice(0, ml);
                    }
                    if (pos > last_match_pos + TRAILING_LITERALS
                        || price <= opt[pos].price - (int)favorDecSpeed) {
                        if (ml == matchML && last_match_pos < pos) last_match_pos = pos;
                        opt[pos].mlen = ml;
                        opt[pos].off = offset;
                        opt[pos].litlen = ll;
                        opt[pos].price = price;
                    }
                }
            }
            {   int addLit;
                for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                    opt[last_match_pos + addLit].mlen = 1;
                    opt[last_match_pos + addLit].off = 0;
                    opt[last_match_pos + addLit].litlen = addLit;
                    opt[last_match_pos + addLit].price = opt[last_match_pos].price + literalsPrice(addLit);
                }
            }
        }

        best_mlen = opt[last_match_pos].mlen;
        best_off = opt[last_match_pos].off;
        cur = last_match_pos - best_mlen;

encode:
        {   int candidate_pos = cur;
            int selected_matchLength = best_mlen;
            int selected_offset = best_off;
            while (1) {
                int const next_matchLength = opt[candidate_pos].mlen;
                int const next_offset = opt[candidate_pos].off;
                opt[candidate_pos].mlen = selected_matchLength;
                opt[candidate_pos].off = selected_offset;
                selected_matchLength = next_matchLength;
                selected_offset = next_offset;
                if (next_matchLength > candidate_pos) break;
                candidate_pos -= next_matchLength;
            }
        }

        {   int rPos = 0;
            while (rPos < last_match_pos) {
                int const ml = opt[rPos].mlen;
                int const offset = opt[rPos].off;
                if (ml == 1) { ip++; rPos++; continue; }
                rPos += ml;
                if (encodeSequence(UPD(ip, op, anchor), ml, ip - offset, limit, oend)) goto _return_label;
            }
        }
    }

    {   size_t lastRunSize = (size_t)(iend - anchor);
        size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
        size_t const totalSize = 1 + llAdd + lastRunSize;
        if (limit && (op + totalSize > oend)) goto _return_label;
        ip = anchor + lastRunSize;

        if (lastRunSize >= RUN_MASK) {
            size_t accumulator = lastRunSize - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (BYTE)accumulator;
        } else {
            *op++ = (BYTE)(lastRunSize << ML_BITS);
        }
        memcpy(op, anchor, lastRunSize);
        op += lastRunSize;
    }

    *srcSizePtr = (int)(((const char*)ip) - source);
    retval = (int)((char*)op - dst);

_return_label:
    free(opt);
    return retval;
}

/* ------------------------- entry points ------------------------- */

typedef struct { int strat; int nbSearches; U32 targetLength; } cParams_t;

static const cParams_t clTable[LZ4HC_CLEVEL_MAX + 1] = {
    { 0,     2, 16 },
    { 0,     2, 16 },
    { 0,     2, 16 },
    { 0,     4, 16 },
    { 0,     8, 16 },
    { 0,    16, 16 },
    { 0,    32, 16 },
    { 0,    64, 16 },
    { 0,   128, 16 },
    { 0,   256, 16 },
    { 1,    96, 64 },
    { 1,   512, 128 },
    { 1, 16384, LZ4_OPT_NUM },
};

static int compressGenericInternal(LZ4_streamHC* const ctx,
                                   const char* const src, char* const dst,
                                   int* const srcSizePtr, int const dstCapacity,
                                   int cLevel, const int limit)
{
    if ((U32)*srcSizePtr > (U32)LZ4_MAX_INPUT_SIZE) return 0;

    ctx->end += *srcSizePtr;
    if (cLevel < 1) cLevel = LZ4HC_CLEVEL_DEFAULT;
    cLevel = MINI(LZ4HC_CLEVEL_MAX, cLevel);
    {   cParams_t const cParam = clTable[cLevel];
        int const favor = ctx->favorDecSpeed ? favorDecompressionSpeed : favorCompressionRatio;
        int result;

        if (cParam.strat == 0) {
            result = compressHashChain(ctx, src, dst, srcSizePtr, dstCapacity,
                                       cParam.nbSearches, limit);
        } else {
            result = compressOptimal(ctx, src, dst, srcSizePtr, dstCapacity,
                                     cParam.nbSearches, cParam.targetLength, limit,
                                     cLevel == LZ4HC_CLEVEL_MAX, favor);
        }
        if (result <= 0) ctx->dirty = 1;
        return result;
    }
}

void LZ4_setCompressionLevel(LZ4_streamHC* s, int compressionLevel)
{
    if (compressionLevel < 1) compressionLevel = LZ4HC_CLEVEL_DEFAULT;
    if (compressionLevel > LZ4HC_CLEVEL_MAX) compressionLevel = LZ4HC_CLEVEL_MAX;
    s->compressionLevel = (short)compressionLevel;
}

void LZ4_favorDecompressionSpeed(LZ4_streamHC* s, int flag)
{
    s->favorDecSpeed = (int8_t)(flag != 0);
}

void LZ4_initStreamHC(LZ4_streamHC* s)
{
    memset(s, 0, sizeof(*s));
    LZ4_setCompressionLevel(s, LZ4HC_CLEVEL_DEFAULT);
}

void LZ4_resetStreamHC_fast(LZ4_streamHC* s, int compressionLevel)
{
    if (s->dirty) {
        int8_t const favor = s->favorDecSpeed;
        LZ4_initStreamHC(s);
        s->favorDecSpeed = favor;
    } else {
        if (s->end != NULL) s->end -= (size_t)s->prefixStart;
        s->prefixStart = NULL;
    }
    LZ4_setCompressionLevel(s, compressionLevel);
}

int LZ4_compress_HC_extStateHC_fastReset(LZ4_streamHC* s, const char* src, char* dst,
                                         int srcSize, int dstCapacity, int level)
{
    LZ4_resetStreamHC_fast(s, level);
    initInternal(s, (const BYTE*)src);
    if (dstCapacity < LZ4_compressBound(srcSize))
        return compressGenericInternal(s, src, dst, &srcSize, dstCapacity, level, limitedOutput);
    return compressGenericInternal(s, src, dst, &srcSize, dstCapacity, level, notLimited);
}

int LZ4_loadDictHC(LZ4_streamHC* s, const char* dictionary, int dictSize)
{
    if (dictSize > 64 * KB) {
        dictionary += (size_t)dictSize - 64 * KB;
        dictSize = 64 * KB;
    }
    {   int const cLevel = s->compressionLevel;
        int8_t const favor = s->favorDecSpeed;
        LZ4_initStreamHC(s);
        LZ4_setCompressionLevel(s, cLevel);
        s->favorDecSpeed = favor;
    }
    initInternal(s, (const BYTE*)dictionary);
    s->end = (const BYTE*)dictionary + dictSize;
    if (dictSize >= LZ4HC_HASHSIZE) hcInsert(s, s->end - 3);
    return dictSize;
}

static void setExternalDict(LZ4_streamHC* ctxPtr, const BYTE* newBlock)
{
    if (ctxPtr->end >= ctxPtr->prefixStart + 4) hcInsert(ctxPtr, ctxPtr->end - 3);

    ctxPtr->lowLimit = ctxPtr->dictLimit;
    ctxPtr->dictStart = ctxPtr->prefixStart;
    ctxPtr->dictLimit += (U32)(ctxPtr->end - ctxPtr->prefixStart);
    ctxPtr->prefixStart = newBlock;
    ctxPtr->end = newBlock;
    ctxPtr->nextToUpdate = ctxPtr->dictLimit;
}

static int compressContinueGeneric(LZ4_streamHC* ctxPtr, const char* src, char* dst,
                                   int* srcSizePtr, int dstCapacity, int limit)
{
    if (ctxPtr->prefixStart == NULL) initInternal(ctxPtr, (const BYTE*)src);

    if ((size_t)(ctxPtr->end - ctxPtr->prefixStart) + ctxPtr->dictLimit > 2u * GB) {
        size_t dictSize = (size_t)(ctxPtr->end - ctxPtr->prefixStart);
        if (dictSize > 64 * KB) dictSize = 64 * KB;
        LZ4_loadDictHC(ctxPtr, (const char*)(ctxPtr->end) - dictSize, (int)dictSize);
    }

    if ((const BYTE*)src != ctxPtr->end) setExternalDict(ctxPtr, (const BYTE*)src);

    {   const char* sourceEnd = src + *srcSizePtr;
        const BYTE* const dictBegin = ctxPtr->dictStart;
        const BYTE* const dictEnd = ctxPtr->dictStart + (ctxPtr->dictLimit - ctxPtr->lowLimit);
        if ((sourceEnd > (const char*)dictBegin) && ((const BYTE*)src < dictEnd)) {
            if (sourceEnd > (const char*)dictEnd) sourceEnd = (const char*)dictEnd;
            ctxPtr->lowLimit += (U32)(sourceEnd - (const char*)ctxPtr->dictStart);
            ctxPtr->dictStart += (U32)(sourceEnd - (const char*)ctxPtr->dictStart);
            if (ctxPtr->dictLimit - ctxPtr->lowLimit < 4) {
                ctxPtr->lowLimit = ctxPtr->dictLimit;
                ctxPtr->dictStart = ctxPtr->prefixStart;
            }
        }
    }

    return compressGenericInternal(ctxPtr, src, dst, srcSizePtr, dstCapacity,
                                   ctxPtr->compressionLevel, limit);
}

int LZ4_compress_HC_continue(LZ4_streamHC* s, const char* src, char* dst,
                             int srcSize, int dstCapacity)
{
    if (dstCapacity < LZ4_compressBound(srcSize))
        return compressContinueGeneric(s, src, dst, &srcSize, dstCapacity, limitedOutput);
    return compressContinueGeneric(s, src, dst, &srcSize, dstCapacity, notLimited);
}

int LZ4_saveDictHC(LZ4_streamHC* s, char* safeBuffer, int dictSize)
{
    int const prefixSize = (int)(s->end - s->prefixStart);
    if (dictSize > 64 * KB) dictSize = 64 * KB;
    if (dictSize < 4) dictSize = 0;
    if (dictSize > prefixSize) dictSize = prefixSize;
    if (dictSize > 0) memmove(safeBuffer, s->end - dictSize, (size_t)dictSize);
    {   U32 const endIndex = (U32)(s->end - s->prefixStart) + s->dictLimit;
        s->end = (const BYTE*)safeBuffer + dictSize;
        s->prefixStart = s->end - dictSize;
        s->dictLimit = endIndex - (U32)dictSize;
        s->lowLimit = endIndex - (U32)dictSize;
        s->dictStart = s->prefixStart;
        if (s->nextToUpdate < s->dictLimit) s->nextToUpdate = s->dictLimit;
    }
    return dictSize;
}
